using Godot;

namespace Metroidvania.Mapa;

// One room on the world map, generated by GeneradorMapaMundo from the map scenes (never edited by
// hand — tweaks go in MapaMundoConfig.AjustesPosicion). Rect is in world pixels inside its region,
// so the room's own coordinates map straight onto it (room origin = Rect.Position - Origen).
[GlobalClass]
public partial class SalaMapa : Resource
{
	[Export] public string Escena = "";
	[Export] public string Region = "";
	[Export] public Rect2 Rect;
	// Where the scene's (0,0) sits in region coordinates, to place the player's marker.
	[Export] public Vector2 Origen;
	// Region coordinates of the hogueras (SavePoint) in this room.
	[Export] public Vector2[] Hogueras = System.Array.Empty<Vector2>();
	// Region coordinates of "interact" exits (doors, cave mouths) leading to another region.
	[Export] public Vector2[] Puertas = System.Array.Empty<Vector2>();
}
